```pascal
V := set of all vertices in the tree;
I := φ;
while V ≠ φ do
begin
    Select a vertex u ∈ V such that
        u is a leaf (degree ≤ 1) of the forest induced by V;
    V := V - {u};
    if u is such that
        no neighbour of u is in I then I := I ∪ {u}
end;
Output (I);
```

